const MISSION_KEY='javalingo-missions-v1';
let missionState=readLocal(MISSION_KEY,{done:{},drafts:{},attempts:{},daily:null,streak:0,lastDaily:''});
missionState.done=missionState.done||{};missionState.drafts=missionState.drafts||{};missionState.attempts=missionState.attempts||{};
const saveMission=()=>{try{localStorage.setItem(MISSION_KEY,JSON.stringify(missionState))}catch{}};
const missionMsg=(pt,en)=>settings.language==='en'?en:pt;
const stepKey=(mi,si)=>`${MISSIONS[mi].id}:${si}`;
const missionCount=m=>m.steps.filter((s,i)=>missionState.done[`${m.id}:${i}`]).length;
const dayKey=()=>{let d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const hashDay=s=>[...s].reduce((n,c)=>((n*33+c.charCodeAt(0))>>>0),5381);
function currentDaily(){let today=dayKey();if(missionState.daily?.date===today)return missionState.daily;let code=MISSIONS.flatMap((m,mi)=>m.steps.map((_,si)=>({mi,si,key:stepKey(mi,si)}))).find(x=>!missionState.done[x.key])||{mi:0,si:0,key:stepKey(0,0)};
 let errors=Object.values(reviewState.items).filter(x=>!x.resolved).sort((a,b)=>a.last-b.last);let due=errors[0]?.id||null;if(!due){let reviewed=Object.values(reviewState.items).filter(x=>x.resolved&&Date.now()-(x.reviewed||x.last)>24*60*60*1000).sort((a,b)=>(a.reviewed||a.last)-(b.reviewed||b.last));due=reviewed[0]?.id||null}if(!due){let prior=Object.keys(progress.done).filter(id=>/^\w+-\d+-\d+$/.test(id));due=prior.length?prior[hashDay(today)%prior.length]:'inicio-0-0'}
 let unsolved=TRACKS.flatMap(t=>t.topics.flatMap((_,ti)=>Array.from({length:10},(_,q)=>topicId(t,ti,q)))).filter(id=>!progress.done[id]);let concept=unsolved.length?unsolved[hashDay(today+'new')%unsolved.length]:'inicio-0-0';if(concept===due&&unsolved.length>1)concept=unsolved[(hashDay(today+'new')+1)%unsolved.length];missionState.daily={date:today,reviewId:due,conceptId:concept,codeKey:code.key,done:{review:false,concept:false,code:false}};saveMission();return missionState.daily}
function finishDailyPart(part){let d=currentDaily();if(d.done[part])return;d.done[part]=true;saveMission();if(Object.values(d.done).every(Boolean)&&missionState.lastDaily!==d.date){let yesterday=new Date();yesterday.setDate(yesterday.getDate()-1);let y=[yesterday.getFullYear(),String(yesterday.getMonth()+1).padStart(2,'0'),String(yesterday.getDate()).padStart(2,'0')].join('-');missionState.streak=missionState.lastDaily===y?missionState.streak+1:1;missionState.lastDaily=d.date;progress.xp+=25;persist();updateStats();saveMission();toast(missionMsg('Missão do Dia concluída! +25 XP.','Daily Mission complete! +25 XP.'))}else toast(missionMsg('Etapa da Missão do Dia concluída.','Daily Mission step complete.'))}
const previousPracticeDone=onPracticeDone;
onPracticeDone=function(id){previousPracticeDone(id);let d=currentDaily();if(d.reviewId===id)finishDailyPart('review');if(d.conceptId===id)finishDailyPart('concept')};
let missionSelection={mi:0,si:0},editorSource='',editorOutput=null,editorError='',editorPopulated=false,missionFeedback=null,missionHint=0;
const previousRender=render;
render=function(){if(screen==='missions'){setNav();updateStats();renderMissions();applyLanguage();return}previousRender()};
const previousSetNav=setNav;
setNav=function(){previousSetNav();if(screen==='missions')$('#breadcrumb').textContent=missionMsg('Missões reais','Real missions')};
const previousRenderHome=renderHome;
renderHome=function(){previousRenderHome();let hero=app.querySelector('.home-hero');if(hero)hero.insertAdjacentHTML('afterend',dailyBanner())};
function dailyBanner(){let d=currentDaily(),total=Object.values(d.done).filter(Boolean).length;return `<button class="daily-banner" data-action="open-missions" aria-label="${missionMsg('Abrir Missão do Dia','Open Daily Mission')}"><span class="daily-symbol">${icon('spark')}</span><span><strong>${missionMsg('Missão do Dia','Daily Mission')}</strong><small>${missionMsg('Uma revisão, uma descoberta e um trecho de código.','One review, one new idea and one piece of code.')}</small></span><span class="daily-meter">${total}/3 ${icon('arrow')}</span></button>`}
function renderMissions(){let d=currentDaily(),mi=missionSelection.mi,si=missionSelection.si,m=MISSIONS[mi],s=m.steps[si],key=stepKey(mi,si),done=!!missionState.done[key];const labels=[missionMsg('Revisar','Review'),missionMsg('Descobrir','Discover'),missionMsg('Codar','Code')];let daily=`<section class="mission-daily"><div><span class="eyebrow">${missionMsg('5 MINUTOS PARA EVOLUIR','A FEW MINUTES TO GROW')}</span><h1>${missionMsg('Sua Missão do Dia','Your Daily Mission')}</h1><p>${missionMsg('Uma tarefa de cada tipo. O conteúdo muda a cada dia e usa seus erros e seu progresso.','One task of each kind. Today’s mix uses your mistakes and progress.')}</p></div><div class="daily-tasks">${['review','concept','code'].map((part,i)=>`<button class="daily-task ${d.done[part]?'done':''}" data-daily="${part}"><span>${d.done[part]?icon('check'):String(i+1).padStart(2,'0')}</span><strong>${labels[i]}</strong><small>${d.done[part]?missionMsg('Feito','Done'):i===0?missionMsg('Um ponto para fixar','Recall one idea'):i===1?missionMsg('Um conceito novo','One new idea'):missionMsg('Código que roda','Code that runs')}</small></button>`).join('')}</div><div class="daily-foot">${missionMsg('Sequência de dias completos','Completed-day streak')}: <strong>${missionState.streak}</strong> · ${Object.values(d.done).filter(Boolean).length}/3 ${missionMsg('etapas hoje','steps today')}</div></section>`;
let campaigns=`<div class="section-heading"><div><span class="eyebrow">${missionMsg('CONSTRUA ALGO DE VERDADE','BUILD SOMETHING REAL')}</span><h2>${missionMsg('Campanha de projetos','Project campaign')}</h2></div><small>${missionMsg('Cada etapa usa Java executável','Every step uses runnable Java')}</small></div><div class="campaign-grid">${MISSIONS.map((c,i)=>`<button class="campaign-card ${i===mi?'active':''}" data-campaign="${i}" style="--accent:${c.color}"><span class="track-icon">${icon(c.icon)}</span><span><strong>${esc(missionMsg(c.title,c.en))}</strong><small>${missionCount(c)}/${c.steps.length} ${missionMsg('etapas','steps')}</small></span>${icon('arrow')}</button>`).join('')}</div>`;
let steps=`<div class="mission-steps">${m.steps.map((st,i)=>`<button class="mission-step ${mi===missionSelection.mi&&i===si?'active':''} ${missionState.done[stepKey(mi,i)]?'done':''}" data-step="${i}"><span>${missionState.done[stepKey(mi,i)]?icon('check'):String(i+1).padStart(2,'0')}</span><strong>${esc(missionMsg(st.title,st.en))}</strong></button>`).join('')}</div>`;
let explain=missionFeedback?`<div class="mission-feedback ${missionFeedback.ok?'success':'problem'}" role="status"><strong>${esc(missionFeedback.title)}</strong><p>${esc(missionFeedback.detail)}</p><p>${missionMsg('Analogia','Analogy')}: ${esc(missionMsg(s.analogy,s.analogyEn))}</p>${missionFeedback.ok&&si<m.steps.length-1?`<button class="button button-secondary" data-action="next-mission-step">${missionMsg('Próxima etapa','Next step')} ${icon('arrow')}</button>`:''}</div>`:'';
let hints=missionHint?`<div class="mission-hint"><strong>${missionMsg('Pista','Hint')} ${missionHint}/3</strong><p>${esc(missionMsg(s.hint[missionHint-1],s.hintEn[missionHint-1]))}</p></div>`:'';
let editor=`<div class="mission-workspace"><div class="mission-workspace-head"><span class="eyebrow">${missionMsg('ETAPA','STEP')} ${si+1}/${m.steps.length} · ${esc(missionMsg(m.title,m.en))}</span>${done?`<span class="mission-complete">${icon('check')} ${missionMsg('Concluída','Completed')}</span>`:''}<h2>${esc(missionMsg(s.title,s.en))}</h2><p>${esc(missionMsg(s.story,s.storyEn))}</p><div class="task-brief"><strong>${missionMsg('Sua tarefa','Your task')}</strong><p>${esc(missionMsg(s.task,s.taskEn))}</p><span>${missionMsg('Saída esperada','Expected output')}:</span><pre>${esc(s.expected)}</pre></div></div><div class="mission-code"><div class="mission-editor-head"><strong>${icon('code')} Java · Main.java</strong><span>${missionMsg('Edite e execute no quadro abaixo','Edit and run in the panel below')}</span></div><iframe id="mission-editor" title="${missionMsg('Editor Java executável','Runnable Java editor')}" src="https://onecompiler.com/embed/java?listenToEvents=true&codeChangeEvent=true&hideLanguageSelection=true&hideNew=true&hideTitle=true&theme=${settings.theme==='dark'?'dark':'light'}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin"></iframe><p class="third-party-note">${missionMsg('Execução por OneCompiler. O código enviado no editor é processado por esse serviço.','Execution by OneCompiler. Code entered here is processed by that service.')}</p><div class="mission-controls"><button class="button button-secondary" data-action="mission-hint">${icon('spark')} ${missionMsg('Pedir pista','Get hint')} ${missionHint}/3</button><button class="button button-primary" data-action="verify-mission">${icon('check')} ${missionMsg('Verificar meu código','Check my code')}</button></div>${hints}${editorOutput!==null?`<div class="run-output"><strong>${missionMsg('Saída recebida','Received output')}</strong><pre>${esc(editorOutput)}</pre></div>`:''}${editorError?`<div class="run-error"><strong>${missionMsg('Erro de compilação ou execução','Compile or runtime error')}</strong><pre>${esc(editorError)}</pre></div>`:''}${explain}<details class="manual-check"><summary>${missionMsg('A saída não apareceu no JavaLingo? Verificação manual','Output not shown here? Manual check')}</summary><p>${missionMsg('Execute no quadro acima e copie a saída. Se a comunicação com o editor não funcionar, cole seu código e a saída nos campos abaixo.','Run in the panel above and copy the output. If the editor cannot send it here, paste your code and output below.')}</p><label>${missionMsg('Código que você executou','Code you ran')}<textarea id="missionFallbackCode" spellcheck="false">${esc(editorSource||missionState.drafts[key]||'')}</textarea></label><label>${missionMsg('Saída exibida pelo compilador','Output shown by the compiler')}<textarea id="missionFallbackOutput" spellcheck="false" placeholder="${missionMsg('Cole a saída, não o texto dos erros','Paste output, not compiler errors')}"></textarea></label><button class="button button-plain" data-action="verify-manual">${missionMsg('Comparar saída','Compare output')}</button></details></div></div>`;
app.innerHTML=`${daily}${campaigns}<section class="mission-panel">${steps}${editor}</section><p class="footnote">${missionMsg('O verificador compara a saída esperada e o conceito pedido. Ele não prova todos os casos possíveis; experimente entradas novas antes de usar seu programa fora daqui.','The checker compares expected output and the requested concept. It does not prove every possible case; try new inputs before using your program elsewhere.')}</p>${m.id==='swingquest'?`<button class="button button-secondary" data-action="open-swing">${missionMsg('Levar a ideia ao laboratório Swing','Continue in the Swing lab')} ${icon('arrow')}</button>`:''}`;
}
function openExercise(id){let {trackId:tr,topicId:ti,questionId:q}=parseJavaPracticeId(id);track=findJavaTrack(tr);if(!track)return;startLesson(Number(ti));lesson.q=Number(q);selected=null;answered=false;codeAnswer='';render();window.scrollTo(0,0)}
function selectMission(mi,si){missionSelection={mi,si};missionHint=0;missionFeedback=null;editorOutput=null;editorError='';editorSource=missionState.drafts[stepKey(mi,si)]||MISSIONS[mi].steps[si].starter;editorPopulated=false;screen='missions';render();setTimeout(()=>app.querySelector('.mission-panel')?.scrollIntoView({block:'start',behavior:'smooth'}),0)}
function postToEditor(payload){let iframe=$('#mission-editor');if(iframe?.contentWindow)iframe.contentWindow.postMessage(payload,'https://onecompiler.com')}
function initializeEditor(){const {mi,si}=missionSelection,key=stepKey(mi,si),frame=$('#mission-editor');editorSource=missionState.drafts[key]||MISSIONS[mi].steps[si].starter;editorPopulated=false;setTimeout(()=>{if(screen==='missions'&&$('#mission-editor')===frame){postToEditor({eventType:'populateCode',language:'java',files:[{name:'Main.java',content:editorSource}]});editorPopulated=true}},450)}
app.addEventListener('load',e=>{if(e.target.id==='mission-editor')initializeEditor()},true);
function parseResult(data){let r=data?.result&&typeof data.result==='object'?data.result:data;if(!r||typeof r!=='object')return null;let error=String(r.stderr||r.exception||r.error||'').trim(),output=typeof r.stdout==='string'?r.stdout:typeof r.output==='string'?r.output:null;if(!error&&output===null)return null;return {output,error}}
window.addEventListener('message',e=>{if(e.origin!=='https://onecompiler.com'||e.source!==$('#mission-editor')?.contentWindow||screen!=='missions')return;let data=e.data;if(typeof data==='string'){try{data=JSON.parse(data)}catch{return}}if(!data||typeof data!=='object'||data.language&&String(data.language).toLowerCase()!=='java')return;const files=Array.isArray(data.files)?data.files:[];let code=files.find(f=>/\.java$/i.test(f.name||''))?.content||files[0]?.content;if(editorPopulated&&typeof code==='string'&&code.length<=50000){editorSource=code;missionState.drafts[stepKey(missionSelection.mi,missionSelection.si)]=code;saveMission();let fallback=$('#missionFallbackCode');if(fallback&&document.activeElement!==fallback)fallback.value=code}let result=parseResult(data);if(result){editorOutput=result.output;editorError=result.error;const out=app.querySelector('.run-output');if(out)out.querySelector('pre').textContent=editorOutput||'';else if(editorOutput!==null){let controls=app.querySelector('.mission-controls');controls?.insertAdjacentHTML('afterend',`<div class="run-output"><strong>${missionMsg('Saída recebida','Received output')}</strong><pre>${esc(editorOutput)}</pre></div>`)}if(result.error){let existing=app.querySelector('.run-error');if(existing)existing.querySelector('pre').textContent=result.error;else app.querySelector('.mission-controls')?.insertAdjacentHTML('afterend',`<div class="run-error"><strong>${missionMsg('Erro de compilação ou execução','Compile or runtime error')}</strong><pre>${esc(result.error)}</pre></div>`)}}});
function normalizeOutput(value){return String(value||'').replace(/\r\n/g,'\n').split('\n').map(x=>x.trimEnd()).join('\n').trim()}
function evaluateMission(code,output,manual=false){let {mi,si}=missionSelection,s=MISSIONS[mi].steps[si],key=stepKey(mi,si);if(!code.trim()){missionFeedback={ok:false,title:missionMsg('Preciso ler seu código','I need to read your code'),detail:missionMsg('Edite o código no quadro. Se ele não se comunicar com esta página, use os campos de verificação manual.','Edit the code in the panel. If it cannot communicate with this page, use the manual check fields.')};renderMissionFeedback();return}
if(output===null||output===undefined){missionFeedback={ok:false,title:missionMsg('Execute antes de verificar','Run before checking'),detail:missionMsg('Clique em Run no editor. Se a saída não chegar aqui, copie-a para a verificação manual abaixo.','Click Run in the editor. If output does not arrive here, copy it into manual check below.')};renderMissionFeedback();return}
if(editorError&&!manual){missionFeedback={ok:false,title:missionMsg('O Java encontrou um erro','Java found an error'),detail:editorError.slice(0,700)};recordMissionAttempt(key,code,output,false);renderMissionFeedback();return}
let actual=normalizeOutput(output),expected=normalizeOutput(s.expected),concept=s.requires.test(code);if(actual!==expected){missionFeedback={ok:false,title:missionMsg('A saída ainda não confere','The output does not match yet'),detail:missionMsg(`Esperado: ${expected.replace(/\n/g,' | ')}. Obtido: ${actual.slice(0,120).replace(/\n/g,' | ')||'(vazio)'}. Reveja o cálculo e tente de novo.`,`Expected: ${expected.replace(/\n/g,' | ')}. Received: ${actual.slice(0,120).replace(/\n/g,' | ')||'(empty)'}. Check your logic and try again.`)};recordMissionAttempt(key,code,output,false);renderMissionFeedback();return}
if(!concept){missionFeedback={ok:false,title:missionMsg('Saída certa, falta o conceito pedido','Correct output, missing the requested concept'),detail:missionMsg('Seu programa mostrou o texto esperado, mas não encontramos a estrutura solicitada no código. Reveja o enunciado; não basta escrever a saída pronta.','Your program showed the expected text, but the requested structure is missing from the code. Check the task; printing a fixed answer is not enough.')};recordMissionAttempt(key,code,output,false);renderMissionFeedback();return}
missionFeedback={ok:true,title:missionMsg('Sua solução passou neste teste!','Your solution passed this test!'),detail:manual?missionMsg('A saída colada corresponde e o código inclui o conceito. Esta verificação depende do resultado que você informou; experimente outro caso também.','Pasted output matches and your code includes the concept. This check depends on the output you entered; try another case too.'):missionMsg('A saída executada corresponde e o código inclui o conceito. Experimente mudar os dados para fortalecer a solução.','The executed output matches and the code includes the concept. Try changing the input to strengthen your solution.')};recordMissionAttempt(key,code,output,true);if(!missionState.done[key]){missionState.done[key]=Date.now();progress.xp+=30;persist();updateStats();saveMission()}if(currentDaily().codeKey===key)finishDailyPart('code');renderMissionFeedback()}
function recordMissionAttempt(key,code,output,ok){let attempts=missionState.attempts[key]||[];attempts.push({at:Date.now(),code:code.slice(0,10000),output:String(output||'').slice(0,3000),ok});missionState.attempts[key]=attempts;saveMission()}
const previousRenderReview=renderReview;
renderReview=function(){previousRenderReview();if(reviewFilter.track!=='all'||reviewFilter.topic!=='all')return;let items=Object.entries(missionState.attempts).filter(([,history])=>history.some(x=>!x.ok)).map(([key,history])=>{let [id,index]=key.split(':'),mi=MISSIONS.findIndex(x=>x.id===id),si=Number(index);if(mi<0||!MISSIONS[mi].steps[si])return null;return {key,mi,si,history,last:history[history.length-1],resolved:!!history[history.length-1].ok}}).filter(Boolean).filter(x=>(reviewFilter.status==='open'?!x.resolved:reviewFilter.status==='resolved'?x.resolved:true)).filter(x=>[MISSIONS[x.mi].title,MISSIONS[x.mi].en,MISSIONS[x.mi].steps[x.si].title,MISSIONS[x.mi].steps[x.si].en].join(' ').toLocaleLowerCase().includes(reviewFilter.search.toLocaleLowerCase()));if(!items.length)return;let html=`<section class="mission-review"><div class="section-heading"><div><span class="eyebrow">${missionMsg('CÓDIGO E PROJETOS','CODE AND PROJECTS')}</span><h2>${missionMsg('Tentativas das missões','Mission attempts')}</h2></div><small>${items.length} ${missionMsg('etapas com erros registrados','steps with recorded errors')}</small></div><div class="review-list">${items.map(x=>{let m=MISSIONS[x.mi],s=m.steps[x.si],failures=x.history.filter(a=>!a.ok);return `<article class="review-card ${x.resolved?'resolved':''}"><div class="review-card-head"><span class="review-tag">${esc(missionMsg(m.title,m.en))}</span><span class="review-status">${x.resolved?missionMsg('Revisado','Resolved'):missionMsg('Para revisar','To review')}</span></div><h2>${esc(missionMsg(s.title,s.en))}</h2><p>${esc(missionMsg(s.task,s.taskEn))}</p><div class="review-answers"><p><strong>${missionMsg('Sua última saída com erro','Your last mismatched output')}:</strong> <code>${esc(failures[failures.length-1].output||'(vazio)')}</code></p><p><strong>${missionMsg('Saída esperada','Expected output')}:</strong> <code>${esc(s.expected)}</code></p></div><p class="review-analogy"><strong>${missionMsg('Analogia','Analogy')}:</strong> ${esc(missionMsg(s.analogy,s.analogyEn))}</p><details class="review-history"><summary>${missionMsg('Rever código e tentativas','Review code and attempts')} (${x.history.length})</summary><ol>${x.history.map(a=>`<li><time>${new Date(a.at).toLocaleString(settings.language==='en'?'en-US':'pt-BR')}</time> · ${a.ok?'✓':'×'}<pre class="mission-attempt-code">${esc(a.code)}</pre></li>`).join('')}</ol></details><div class="review-card-foot"><span>${failures.length} ${missionMsg('erros registrados','recorded mistakes')}</span><button class="button button-secondary" data-mission-retry="${esc(x.key)}">${missionMsg('Refazer missão','Retry mission')} ${icon('arrow')}</button></div></article>`}).join('')}</div></section>`;let empty=app.querySelector('.review-empty');if(empty&&Object.keys(reviewState.items).length===0)empty.remove();app.insertAdjacentHTML('beforeend',html)};
function renderMissionFeedback(){let el=$('.mission-feedback');let {mi,si}=missionSelection,s=MISSIONS[mi].steps[si];let html=`<div class="mission-feedback ${missionFeedback.ok?'success':'problem'}" role="status"><strong>${esc(missionFeedback.title)}</strong><p>${esc(missionFeedback.detail)}</p><p>${missionMsg('Analogia','Analogy')}: ${esc(missionMsg(s.analogy,s.analogyEn))}</p>${missionFeedback.ok&&si<MISSIONS[mi].steps.length-1?`<button class="button button-secondary" data-action="next-mission-step">${missionMsg('Próxima etapa','Next step')} ${icon('arrow')}</button>`:''}</div>`;if(el)el.outerHTML=html;else $('.mission-controls')?.insertAdjacentHTML('afterend',html);let marker=$('.mission-complete');if(missionFeedback.ok&&!marker){$('.mission-workspace-head .eyebrow')?.insertAdjacentHTML('afterend',`<span class="mission-complete">${icon('check')} ${missionMsg('Concluída','Completed')}</span>`)}}
app.addEventListener('click',e=>{let b=e.target.closest('[data-campaign],[data-step],[data-daily],[data-mission-retry],button[data-action]');if(!b)return;if(b.dataset.missionRetry){let [id,index]=b.dataset.missionRetry.split(':'),mi=MISSIONS.findIndex(x=>x.id===id);if(mi>=0)selectMission(mi,Number(index));return}if(b.dataset.campaign!==undefined){selectMission(Number(b.dataset.campaign),0);return}if(b.dataset.step!==undefined){selectMission(missionSelection.mi,Number(b.dataset.step));return}if(b.dataset.daily){let d=currentDaily();if(b.dataset.daily==='review')openExercise(d.reviewId);if(b.dataset.daily==='concept')openExercise(d.conceptId);if(b.dataset.daily==='code'){let [campaign,index]=d.codeKey.split(':');selectMission(MISSIONS.findIndex(x=>x.id===campaign),Number(index))}return}switch(b.dataset.action){case 'open-missions':navigate('missions');break;case 'open-swing':navigate('lab');break;case 'mission-hint':missionHint=Math.min(3,missionHint+1);let s=MISSIONS[missionSelection.mi].steps[missionSelection.si];let hint=app.querySelector('.mission-hint');let markup=`<div class="mission-hint"><strong>${missionMsg('Pista','Hint')} ${missionHint}/3</strong><p>${esc(missionMsg(s.hint[missionHint-1],s.hintEn[missionHint-1]))}</p></div>`;if(hint)hint.outerHTML=markup;else app.querySelector('.mission-controls')?.insertAdjacentHTML('afterend',markup);b.textContent=`${missionMsg('Pedir pista','Get hint')} ${missionHint}/3`;break;case 'verify-mission':evaluateMission(editorSource,editorOutput);break;case 'verify-manual':{let code=$('#missionFallbackCode')?.value||editorSource,output=$('#missionFallbackOutput')?.value;editorError='';evaluateMission(code,output,true);break}case 'next-mission-step':selectMission(missionSelection.mi,Math.min(MISSIONS[missionSelection.mi].steps.length-1,missionSelection.si+1));break}},false);
render();
